INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (31, '2', '2', '1', '詞句朗讀', '1', '', '', '', '', '請汝唸出這句話： 「大家齊齊跳索真有味」', NULL, 'MT17.mp3,MT1701.mp3', '', '請汝唸出這句話： 「大家齊齊跳索真有味」', '5', '2025/macuhau-t/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (32, '2', '2', '1', '詞句朗讀', '2', '', '', '', '', '請汝唸出這句話： 「我對手依嬭做家事。」', NULL, 'MT18.mp3,MT1801.mp3', '', '請汝唸出這句話： 「我對手依嬭做家事。」', '5', '2025/macuhau-t/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (33, '2', '2', '2', '情境對話', '1', '', '', '', '', '汝厝咧有使什乇電器用品？請汝講出 5種用品名稱。', NULL, 'MT19.mp3,MT1901.mp3', '', '電視、電腦、電冰箱、冷氣、 電光、電風扇、電鍋、烤箱、吹風機、洗衣機', '10', '2025/macuhau-t/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (34, '2', '2', '2', '情境對話', '2', '', '', '', '', '汝敆厝咧對手過什乇家事?做這項工作的辰候，著注意什乇？\r\n\r\n', NULL, 'MT20.mp3,MT2001.mp3', '', '我有對手洗碗。\r\n洗碗著注意：\r\n先揢剩菜底勢的湯汁倒澈潔，沒耐讓水管塞呵。\r\n使洗碗精先洗比較澈潔的碗共盤盤，接著再洗鍋鍋鼎囝。\r\n洗完著沖澈潔，無留沫沫，再廮通風位置晾燋。', '10', '2025/macuhau-t/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (35, '2', '2', '2', '情境對話', '3', '', '', '', '', '略', NULL, '', '', '', '10', '2025/macuhau-t/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (36, '2', '2', '2', '情境對話', '4', '', '', '', '', '略', NULL, '', '', '', '10', '2025/macuhau-t/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (37, '2', '2', '3', '看圖講話', '1', '', '', '', '', '問題：講蜀講，只兩張圖底勢，下課辰候，學生做什乇活動？', NULL, 'MT21.mp3,MT2101.mp3', 'MT21.jpg', '學生下課辰後，敆操埕歡喜的攀講、拍籃球、齊齊?步、齊齊跳索。\r\n\r\n', '10', '2025/macuhau-t/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (38, '2', '2', '3', '看圖講話', '2', '', '', '', '', '問題：請講蜀講，每蜀張圖代表什乇辰候，適合做什乇事計，汝有耐每蜀張圖簡單講兩三句就會使，但是每蜀張圖一定都著講著。\r\n', NULL, 'MT22.mp3,MT2201.mp3', 'MT22.jpg', '春天花園底勢開滿花，蝴蝶飛來飛去，像蜀幅畫。\r\n夏天天氣熱，食冰野透骹。\r\n秋天楓箬紅丹丹，看起呵野俊。\r\n冬天落雪辰候，儂家有耐去堆雪人。', '10', '2025/macuhau-t/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (39, '2', '2', '3', '看圖講話', '3', '', '', '', '', '問題：只有四張圖，每蜀張圖使3、4句話講出伊的意思，合起來變蜀其故事。（請盡量發揮，但四張圖一定都著講著。）', NULL, 'MT23.mp3,MT2301.mp3,MT2302.mp3', 'MT23.jpg', '圖1.有蜀頭兔共烏龜比賽?步。\r\n圖2.比賽開始無若?，兔子已經?遘天地遠呵了，烏龜固咧慢慢爬。\r\n圖3.兔子想：「我睏飽爬起來，一定固是會比伊快。」烏龜搏䋾慢慢爬，蜀墿都沒休息。\r\n圖4.等兔子睏飽趕上辰候，烏龜盡早就爬遘了，吶兔子自家拍神意。\r\n', '20', '2025/macuhau-t/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (40, '3', '3', '1', '語詞語法', '1', '姿娘囝', '老嬤', '丈夫囝', '老公', '「這隻是我厝裡」，請問底勢的「厝裡」共下底典哪其意思最接近?\n', NULL, '', '', 'B', '3', '2025/macuhau-t/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (41, '3', '3', '1', '語詞語法', '2', '工作努力', '辯論爭議', '打架滋事', '預測命運', '「依爹講做人著搏䋾」。請問底勢的「搏䋾」是什乇意思?', NULL, '', '', 'A', '3', '2025/macuhau-t/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (42, '3', '3', '1', '語詞語法', '3', '天氣涼涼略', '天氣變凊呵', '天氣?穩定', '天氣卜變了', '「依嬤講涼九熻三的道理乞儂家聽。」請問底勢的「涼九熻三」」是什乇意思?', NULL, '', '', 'C', '3', '2025/macuhau-t/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (43, '3', '3', '1', '語詞語法', '4', '燒烤', '鍛鐵', '口渴', '失火', '「依弟跟同學去拍籃球，轉厝告喙燋。」請問「喙燋」是什乇意思？', NULL, '', '', 'C', '3', '2025/macuhau-t/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (44, '3', '3', '1', '語詞語法', '5', '?愛坐車 ', '?坐著車 ', ' 特尾坐車 ', '坐著車尾', '「 依妹?赴搭著特尾蜀班車。」意思是講依妹蔣祈？', NULL, '', '', 'B', '3', '2025/macuhau-t/TAA', NULL, NULL, NULL, NULL);
