INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (187, '4', '4', '1', '聽寫漢字', '1', '', '', '', '', '', NULL, '2025MAW01.mp3', '', '「獃天」。「昨暝風透復盪雨是獃天。」的獃天，獃天。', '2', '2025/macuhau/TAA', NULL, NULL, NULL, NULL);
