INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (189, '4', '4', '1', '聽寫漢字', '3', '', '', '', '', '', NULL, '2025MAW03.mp3', '', '「個郎」。「今旦個郎下晝都咧盪雨。」的個郎，個郎。', '2', '2025/macuhau/TAA', NULL, NULL, NULL, NULL);
