INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (191, '4', '4', '1', '聽寫漢字', '5', '', '', '', '', '', NULL, '2025MAW05.mp3', '', '「卵糕」。「依爹買卵糕乞我過生日。」的卵糕，卵糕。', '2', '2025/macuhau/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (192, '4', '4', '1', '聽寫漢字', '6', '', '', '', '', '', NULL, '2025MAW06.mp3', '', '「細膩」。「伊做事計野細膩。」的細膩，細膩。', '2', '2025/macuhau/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (193, '4', '4', '1', '聽寫漢字', '7', '', '', '', '', '', NULL, '2025MAW07.mp3', '', '「目睭」。「依妹的兩粒目睭復烏復大。」的目睭，目睭。', '2', '2025/macuhau/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (194, '4', '4', '1', '聽寫漢字', '8', '', '', '', '', '', NULL, '2025MAW08.mp3', '', '「目睭」。「依妹的兩粒目睭復烏復大。」的目睭，目睭。', '2', '2025/macuhau/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (195, '4', '4', '1', '聽寫漢字', '9', '', '', '', '', '', NULL, '2025MAW09.mp3', '', '「沃水」。「栽栽好儷著沃水。」的沃水，沃水。', '2', '2025/macuhau/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (196, '4', '4', '3', '塌空測驗', '1', '', '', '', '', '我今旦無注意著馬墿跋倒了，真＿（1）＿，乞野?儂看見著。', NULL, '', '', '無?', '4', '2025/macuhau/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (197, '4', '4', '3', '塌空測驗', '2', '', '', '', '', '五月節的辰侯，依嬤有準備花生、香菇、肉、＿（2）＿，裹粽乞儂家吃。', NULL, '', '', '粽箬、卵黃、秫米、金豆', '4', '2025/macuhau/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (198, '4', '4', '3', '塌空測驗', '3', '', '', '', '', '海裡有各種魚，有大的、＿（3）＿，也有紅紅的魚囝。', NULL, '', '', '嫩的', '4', '2025/macuhau/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (199, '4', '4', '3', '塌空測驗', '4', '', '', '', '', '風颱卜來了，儂家快去準備＿（4）＿，免得停電看?著。', NULL, '', '', '手電、燭', '4', '2025/macuhau/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (200, '4', '4', '3', '塌空測驗', '5', '', '', '', '', '春水的天氣，講變就變，出門著記得帶＿（5）＿，若會凊，馬上頌起呵，總款乍?感冒。', NULL, '', '', '外套', '4', '2025/macuhau/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (201, '4', '4', '3', '塌空測驗', '6', '', '', '', '', '天暗了，依嬤驚電費貴，?捨開＿（6）＿，客廳會做黜黜烏的！', NULL, '', '', '電光', '4', '2025/macuhau/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (202, '4', '4', '3', '塌空測驗', '7', '', '', '', '', '許蜀間餐廳的料理真＿（7）＿，伓啻?澈潔，固加啦飯菜煮?熟，以後都莫去了。', NULL, '', '', '擸?、伓好食', '4', '2025/macuhau/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (203, '4', '4', '3', '塌空測驗', '8', '', '', '', '', '學生囡仔睏眠(目冒)就愛正常，莫著三更＿（8）＿伓睏，直透骹遛手機，身體會做獃呵。', NULL, '', '', '半暝', '4', '2025/macuhau/TAA', NULL, NULL, NULL, NULL);
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (204, '4', '4', '4', '語句書寫', '1', '', '', '', '', '問題：同學得著全縣馬祖語作文頭頭名，請汝寫蜀張卡片恭喜伊。（30字以內）\r\n', NULL, '', '', '每蜀巡看著汝認真學習的樣式都讓儂家真感動，為了只巡的比賽汝準備了野日行的時間，雖然辛苦但是都無放棄，是儂家大家的好榜樣', '10', '2025/macuhau/TAA', NULL, NULL, NULL, NULL);
