INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (270, '1', '1', '2', '演說理解', '1', '有耐增加居民搬轉。', '過小年拜神求平安。', '敆三十暝暝晡舉行。', '出門倪囝都會轉來。', '根據演說，有關擺暝的講法，下底底蜀其正確？', NULL, 'MBS01.mp3', '', 'B', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '');
