INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (282, '1', '1', '2', '演說理解', '13', '半爿雞伓中分年。', '食飽曲厝做郎郎。', '伓別駛船怪溪彎。', '?食蜀鼎伓別餡。', '根據演說，先生罵伊，是因為伊學習態度蔣祈？ ', NULL, 'MBS13.mp3', '', 'A', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '');
