INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (285, '2', '2', '1', '情境對話', '1', '', '', '', '', '問題：地震來的辰候，汝會怎合做？請使幾句話講出。', NULL, 'MC01.mp3,MC0101.mp3', '', '', '10', '2025/macuhau/TBA', NULL, NULL, NULL, '');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (286, '2', '2', '2', '看圖講話', '1', '', '', '', '', '問題：只有四張圖，每蜀張圖使3、4句話講出伊的意思，合起來變蜀其故事。（請盡量發揮，但四張圖一定都著講著。）', NULL, 'MC02.mp3,MC0201.mp3,MC0202.mp3', 'MT1.jpg', '', '10', '2025/macuhau/TBA', NULL, NULL, NULL, '');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (290, '2', '2', '3', '文章朗讀', '1', '', '', '', '', '我讀小學四年級許蜀年，放暑假辰候，儂家蜀厝去鄉下依公厝住。依公的厝是瓦厝，厝前斗有大大的埕，倪囝羔有耐敆只跳索、?步、骹遛、騎骹踏車。厝正邊有蜀其菜園，底勢栽蕹菜、小白菜、瓠、蔥、金瓜，早起頭我共依妹會跟依嬤去菜園沃水，依嬤講：「這劣菜無蟲藥，是儂家每蜀日飯頓的配，食的安全復有營養。」厝左邊有蜀條嫩嫩的河，我稠稠共表兄弟姊妹去骹遛水、泅水，也有辰候敆河旁邊草地野餐，看河底勢的魚泅來泅去，罔食罔攀講，日子過得野爽快。許蜀年夏季的情形，我直透記定定囥心咧，希望有機會再去依公厝住。', NULL, 'MC03.mp3,MC0301.mp3,MC0302.mp3', '', '', '10', '2025/macuhau/TBA', NULL, NULL, NULL, '');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (291, '2', '2', '4', '口語表達', '1', '', '', '', '', '請問汝會捌勢底偌款做，有耐讓自家身體更更健康？', NULL, 'MC04.mp3,MC0401.mp3,MC0402.mp3', '', '', '10', '2025/macuhau/TBA', NULL, NULL, NULL, '');
