INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (308, '3', '3', '1', '語詞語法', '16', '看儂面', '看情形', '看運氣', '看天氣', '「伊這蜀儂野會看別儂目色。」意思是講這位儂蔣祈做事計？', NULL, '', '', 'A', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (309, '3', '3', '1', '語詞語法', '17', '大啜大食', '搏䋾趁錢', '依時辰做', '安份守己', '「依福是頌棉襖食蟟囝，褪??食蛤。」，請問依福這隻儂的生活蔣祈？', NULL, '', '', 'A', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '');
