INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (312, '3', '3', '1', '語詞語法', '20', '拍鑼拍鼓', '唱歌跳舞', '張燈結綵', '敆攤關刀', '「伊蜀遘學校就著教室咧洋鼓洋號。」請問伊敆教室裡做什乇？', NULL, '', '', 'D', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (313, '3', '3', '2', '克漏字', '1', '無管', '無耐', '無想', '無講', '臺灣是蜀其好地方，春夏秋冬都有花好看，__(1)__是草花，__(2)__樹花，各色各樣，汝想會遘想?遘的花種，花色都有。春天蜀遘，桃花先報信，杜鵑花迎風開，接著五月的桐花滿山滿谷像落雪，六七月荷花蓮花開滿水塘，秋天遘，桂花菊花香，冬天伓驚凊的梅花開完儷，__(3)__櫻花開遍全臺，__(4)__臺灣真正是寶島，儂儂都喜歡。', NULL, '', '', 'A', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (314, '3', '3', '2', '克漏字', '2', '也是', '就是', '若是', '固是', '', NULL, '', '', 'D', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '');
