INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (317, '3', '3', '2', '克漏字', '5', '唱歌', '?步', '跳索', '看書', '下課鐘聲蜀響，倪囝羔溜溜衝出教室，馬上開始骹遛。玉美共美玲齊齊__(5)__，蜀邊跳蜀邊笑，笑無停；國強共同學摁咧__(6)__，汝逐我走，?得大汗泄泄落；幾隻丈夫囝敆操埕底勢__(7)__、傳球、投籃，野鬧熱；固有幾隻同學坐敆(木臭)下輕聲__(8)__，分享有味的故事，大家都野歡喜。', NULL, '', '', 'C', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '');
