INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (321, '3', '3', '3', '文章理解', '1', '讓厝裡更更光', '厝裡人丁興旺', '厝裡要修燈具', '想要節省油料', '根據本文，依嬤拭煤氣燈辰候講的話，是希望蔣祈？', '暝晡，澳咧的燈蜀盞蜀盞光起。依嬤敆門喙拭煤氣燈，笑講：「添燈添丁，旺\n旺有光。」厝裡燈暖暖的，照著好睏的倪囝羔，也照著蜀厝儂的笑容。 \n    \n遠遠海面閃著微微光，許是港口的燈塔。從舊底遘現在，伊為轉回的船指路，\n提醒老蕭：「前斗是岸，厝卜遘了。」依公年輕辰後稠稠出海，討生活照顧蜀厝儂，\n每蜀巡遠遠看著許道光，就會捌卜遘厝了。仱伊年歲大了無耐出海，敆厝裡對手\n拭燈，伊伓講話，安靜復堅定的愛長長長，就像燈塔守望著蜀厝儂。 \n    \n暝晡的風輕輕吹，厝兜厝裡的燈齊齊光，蜀盞照生活日常，蜀盞指引轉來，\n蜀盞添福添丁。微微光的燈火蜀盞蜀盞，暝晡變得野暖野靜，幸福野敆著光咧靜\n靜散開。', '', '', 'B', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '文章理解文章:「依爹昨暝晡帶依弟去盝魚。」根據這句話伊別儂最有可能去底哪？');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (322, '3', '3', '3', '文章理解', '2', '固想出海討魚', '享受孤單寂寞', '守候厝裡的愛', '閒閒敆厝裡坐', '根據本文，下底底蜀句有耐表示依公年歲大的辰候，代表的意思是蔣祈？ ', NULL, '', '', 'C', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (323, '3', '3', '3', '文章理解', '3', '暝晡的生驚共孤單', '遠方的生分共祝福', '舊底的想念共退悔', '家庭的溫暖共安定', '根據本文，下底底蜀句適合做這篇文章的主題？', NULL, '', '', 'D', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (324, '3', '3', '3', '文章理解', '4', '想讓先生褒', '別儂也有做', '依婆摜乇吃力', '遘依婆旁邊', '根據本文，作者為什乇會主動去對手依婆？', '對手別儂是蜀件讓自家感覺野歡喜的事計。我有蜀日對手別儂的經驗，讓我體會著對手別儂伓啻有耐讓別儂開心，也有耐讓自家蜀身爽快。\n\n回是去年暝冬天的蜀個早起頭，天氣野凊，我敆放齋的墿上看著蜀隻?彎彎的依婆摜著野重的菜籃，䟰墿擺來擺去的。我心裡想：「伊看起來野辛苦，我去對手伊\n吧！」故此，我䟰遘伊身兜，問依婆安使對手汝？依婆拍神意的點點頭，我就對\n手伊揢菜籃摜遘依婆的厝門喙，伊直透向我道謝，固褒我是蜀隻有禮貌復有熱心\n的倪囝，伊婆蜀面微微笑。 \n\n許辰後，我的心咧感覺暖暖的。對手別儂無需要偌?的力氣，吶啦願意對手\n別儂，就有耐讓世界變得更加美好。捅許遭以後，我更更願意主動對手別儂，因\n為我會捌，許蜀種乞別儂感謝共付出的感覺，是最真實、最美好的幸福。', '', '', 'C', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '文章理解文章:「依爹昨暝晡帶依弟去盝魚。」根據這句話伊別儂最有可能去底哪？');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (325, '3', '3', '3', '文章理解', '5', '對手別儂會得著回報', '對手別儂自家也歡喜', '老儂都需要別儂照顧', '做好事為了別儂褒汝', '根據本文，作者從這次經驗中學著最重要的道理是什乇？', NULL, '', '', 'B', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (326, '3', '3', '3', '文章理解', '6', '是伊的工作', '對儂的關心', '表現體力好', '希望別儂褒', '根據本文，伊問：「依婆安使對手汝？」有耐代表什乇意義？', NULL, '', '', 'B', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (327, '3', '3', '3', '文章理解', '7', '著相信自家', '能力野重要', '對儂有信用', '開會著準時', '根據本文，作者見覺對別儂的基本態度是蔣祈？', '人生的墿野長，做儂固是靜靜仂囝比較好。比換講，有儂請汝去辦事計，汝就想蜀想自家有無總款本事。若有，乍有耐答應。若是跟別儂約定好了，回就盡量發揮自家的能力揢別儂講的事計做好。但是現實社會就是有許蜀種儂，仱儂家拜託伊的辰候，伊都是拍心肝保證，一定有能隑，結果掏著好處以後就溜溜?呵了，無管儂家敆許直透等伊，結果伊莫插儂家蔣祈。捅小處看，這種儂每蜀巡開會辰候，一定都著儂家千交代萬交代著記得，但是伊輕的就是遲到，嚴重的就是無來。伊都是有理由講伊自家野忙，無偌?時間。但是汝問伊忙什乇，伊也講?出原因，反正就是無揢別儂的事計囥心咧。做儂最基本的原則：莫著隨便相信別儂，乍?乞別儂騙；莫著隨便答應別儂，乍?對不住別儂。做儂啊！真正人情留蜀線，日後好見面，講的就是這其道理。', '', '', 'C', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '文章理解文章:「依爹昨暝晡帶依弟去盝魚。」根據這句話伊別儂最有可能去底哪？');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (328, '3', '3', '3', '文章理解', '8', '盡想得著好處', '想讓儂家安心', '表示一定成功', '看重儂家身份', '根據本文，有儂會拍心肝保證是什乇原因？', NULL, '', '', 'C', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (329, '3', '3', '3', '文章理解', '9', '講遘固著做遘', '復七七復八八', '注重別儂本事', '廮儂家敆心底', '根據本文，儂家做儂著蔣祈乍會使？', NULL, '', '', 'A', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (330, '3', '3', '3', '文章理解', '10', '做事計態度?好', '趕急事計做?好', '?捌底偌款開車', '開車技術?酣熟', '根據本文，依爹的行為代表什乇情形？', '暝食儷，蜀厝儂敆客廳咧邊食水果、攀講，邊看電視，聽新聞講汽油明旦會起價，依爹盡像乞雷公拍著蜀樣跳起來告：「什哪？汽油起價？?使！我現在就去加油，伓是?赴了！」伊溜溜掏汽車鎖匙，開門出去，依嬭跟伊後斗提醒伊：「慢仂囝，細膩點，著注意安全！」依爹手擺擺講：「放心，我這隻儂最小心的！」\n幾秒以後，野像聽見車庫底勢有奇怪的聲音。儂家就去覷，結果看見依爹眉頭皺的坐敆車底勢，正邊骹直透踩油門，汽車發出奇怪的聲音，但是伊無發現汽車都無動。依嬭問：「汝到底咧做什乇？汝是暖車固是咧騎骹踏車？」依爹蜀頭大汗講：「奇怪，這架車今旦怎講無耐發動？」依嬭手比鎖匙講：「汝自家覷蜀覷！」這遭依爹乍發現，自己吶顧著快點，結果連車都忘記發動。他抓蜀抓頭講：「唉，洽緊張了，無發現。」蜀厝儂聽了都大笑起呵。依爹無?笑講：「哈哈，想講汽車舊呵了，稠稠著揢車熱蜀熱，乍好開嘛！」依弟敆旁邊講：「依爹，下巡加油辰候著記得先發動大腦，再發動汽車喔！」做蜀下大家復笑翻天呵。', '', '', 'B', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '文章理解文章:「依爹昨暝晡帶依弟去盝魚。」根據這句話伊別儂最有可能去底哪？');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (331, '3', '3', '3', '文章理解', '11', '做事計著細膩', '出門注意安全', '車著稠稠保養', '蜀厝儂都洽好', '根據本文，這篇文章讓儂家了解什乇道理？', NULL, '', '', 'A', '3', '2025/macuhau/TBA', NULL, NULL, NULL, '');
