INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (343, '4', '4', '2', '語句書寫', '1', '', '', '', '', '問題：請使下底的語詞寫出蜀句話（大約 2、3 句），有耐憑自家的意思加語詞，但是，一定著揢下底的語詞寫進去：仂囝、㾤嗽、醫官、故此、復。', NULL, '', '', '', '10', '2025/macuhau/TBA', NULL, NULL, NULL, '');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (344, '4', '4', '2', '語句書寫', '2', '', '', '', '', '問題：朋友掏汝對手，卜出門以前，汝會寫什乇，讓厝咧儂安心。（25-40字）', NULL, '', '', '', '10', '2025/macuhau/TBA', NULL, NULL, NULL, '');
INSERT INTO public.examkind (id, type_number, type, part_number, part, question_number, a, b, c, d, question, long_question, voice, picture, answer, score, kind, text, created, updated, passage) VALUES (345, '4', '4', '3', '文章寫作', '3', '', '', '', '', '問題：汝見覺買乇去店咧買比較好，固是使網路訂的比較好？請寫出汝的看法。（150-200 字之間，答案紙大約 10 行）', NULL, '', '', '', '10', '2025/macuhau/TBA', NULL, NULL, NULL, '');
